**独立参考解答（非原书摘录）**

采用题设的孩子—兄弟结点：\(firstchild\) 指向第一个孩子，\(nextsibling\) 只连接同一双亲的兄弟。树的度是任一结点孩子数的最大值，不能把 \(nextsibling\) 当作二叉树的右孩子来计数。

~~~~c
typedef struct CSNode {
    char data;
    struct CSNode *firstchild, *nextsibling;
} CSNode, *CSTree;

static void ScanForestForDegree(CSTree p, int *best) {
    for (; p != NULL; p = p->nextsibling) {
        int d = 0;
        for (CSTree c = p->firstchild; c != NULL; c = c->nextsibling)
            ++d;
        if (d > *best) *best = d;
        ScanForestForDegree(p->firstchild, best);
    }
}

int TreeDegree(CSTree T) {
    int best = 0;
    ScanForestForDegree(T, &best);
    return best;
}
~~~~

空树返回 \(0\)，单结点树也返回 \(0\)。外层循环恰访问当前森林中的每个根，递归再访问其孩子森林；因此每个树结点恰被检查一次，且 \(d\) 正是该结点的孩子数，\(best\) 即全树最大度。各孩子链至多额外扫描一次，时间为 \(O(n)\)；兄弟用循环而非递归逐个展开，递归辅助空间为 \(O(h)\)，其中 \(h\) 为树的层数。

**独立参考解答（非原书摘录）**

设孩子链表表示为：每个 \(nodes[u]\) 有数据域和指向其孩子链的 \(firstchild\)，孩子链结点保存孩子在结点表中的下标 \(child\)。\(root\) 是根下标。输入前提是该表确为无环、每个非根结点恰有一个双亲的树。

~~~~c
typedef struct ChildNode {
    int child;
    struct ChildNode *next;
} ChildNode, *ChildPtr;

typedef struct { char data; ChildPtr firstchild; } CTBox;
typedef struct {
    CTBox nodes[MAX_TREE_SIZE];
    int n, root;
} CTree;

static int DepthAt(const CTree *T, int u) {
    int deepestChild = 0;
    for (ChildPtr p = T->nodes[u].firstchild; p != NULL; p = p->next) {
        int d = DepthAt(T, p->child);
        if (d > deepestChild) deepestChild = d;
    }
    return deepestChild + 1;
}

int TreeDepth(const CTree *T) {
    if (T == NULL || T->n == 0) return 0;
    return DepthAt(T, T->root);
}
~~~~

叶结点的孩子链为空，故返回 \(1\)；任一非叶结点返回所有孩子子树深度的最大值加 \(1\)，正是以该结点为根的树深度。由此递归式归纳可知根调用给出全树深度。空树返回 \(0\)。每个结点和每条孩子链接各处理一次，时间 \(O(n)\)，递归辅助空间 \(O(h)\)。

**独立参考解答（非原书摘录）**

双亲表的 \(parent\) 域给出双亲下标，根以 \(-1\) 标记。下面用记忆化递归计算每个结点到根的层数，避免对每个结点重复沿双亲链回溯。\(mark=1\) 还能拒绝含环的错误输入；正常树只有一个 \(parent=-1\) 的根。

~~~~c
typedef struct { char data; int parent; } PTNode;
typedef struct { PTNode nodes[MAX_TREE_SIZE]; int n; } PTree;

static Status FillLevel(const PTree *T, int u, int level[], int mark[]) {
    if (mark[u] == 2) return OK;
    if (mark[u] == 1) return ERROR;              /* 双亲链成环 */
    mark[u] = 1;
    int p = T->nodes[u].parent;
    if (p == -1) {
        level[u] = 1;
    } else {
        if (p < 0 || p >= T->n || FillLevel(T, p, level, mark) == ERROR)
            return ERROR;
        level[u] = level[p] + 1;
    }
    mark[u] = 2;
    return OK;
}

Status TreeDepth(const PTree *T, int *H) {
    int level[MAX_TREE_SIZE] = {0};
    int mark[MAX_TREE_SIZE] = {0};
    int roots = 0;
    if (T == NULL || H == NULL || T->n < 0 || T->n > MAX_TREE_SIZE)
        return ERROR;
    if (T->n == 0) { *H = 0; return OK; }
    for (int i = 0; i < T->n; ++i)
        if (T->nodes[i].parent == -1) ++roots;
    if (roots != 1) return ERROR;

    *H = 0;
    for (int i = 0; i < T->n; ++i) {
        if (FillLevel(T, i, level, mark) == ERROR) return ERROR;
        if (level[i] > *H) *H = level[i];
    }
    return OK;
}
~~~~

对根，层数为 \(1\)；对非根，层数恰为其双亲层数加 \(1\)。记忆化后每个表项只完成一次，所以最终最大层数就是树深度。空表输出 \(0\)，父下标越界、多个根或双亲环返回错误。时间 \(O(n)\)，\(level\)、\(mark\) 辅助空间 \(O(n)\)，递归栈 \(O(h)\)。

**独立参考解答（非原书摘录）**

以下以单字符标识为例，\(byName\) 把已出现的标识映射到其孩子—兄弟结点，\(lastChild\) 保留每个双亲当前最后一个孩子。题设中 \(C\) 按层次出现，因而读到非根二元组 \((F,C)\) 时 \(F\) 已经出现；同一双亲的多条边不必连续，仍可用 \(lastChild\) 追加并保持输入中的从左到右次序。

~~~~c
typedef struct CSNode {
    char data;
    struct CSNode *firstchild, *nextsibling;
} CSNode, *CSTree;

Status BuildCSFromPairs(CSTree *T) {
    CSTree byName[256] = {0}, lastChild[256] = {0};
    int rootSeen = 0;
    *T = NULL;

    for (;;) {
        unsigned char F, C;
        if (ReadPair(&F, &C) == ERROR) goto bad;
        if (F == '^' && C == '^') break;
        if (C == '^') goto bad;

        if (F == '^') {
            if (rootSeen || byName[C] != NULL) goto bad;
            *T = NewCSNode(C);
            if (*T == NULL) goto overflow;
            byName[C] = *T;
            rootSeen = 1;
        } else {
            CSTree p = byName[F], q;
            if (p == NULL || byName[C] != NULL) goto bad;
            q = NewCSNode(C);
            if (q == NULL) goto overflow;
            byName[C] = q;
            if (p->firstchild == NULL) p->firstchild = q;
            else lastChild[F]->nextsibling = q;
            lastChild[F] = q;
        }
    }
    if (!rootSeen) goto bad;
    return OK;

overflow:
    DestroyCSTree(*T);
    *T = NULL;
    return OVERFLOW;
bad:
    DestroyCSTree(*T);
    *T = NULL;
    return ERROR;
}
~~~~

\(NewCSNode\) 必须把两个链接域初始化为 \(NULL\)，\(DestroyCSTree\) 释放已建子树。算法拒绝重复标识、第二个根、未出现的双亲和缺少根；题设的合法输入以 \(\texttt{^^}\) 结束。每个结点只分配一次、每条边只链接一次，直接索引标识表时建树时间 \(O(n)\)，辅助表空间 \(O(|\Sigma|)\)；若标识不是字节字符，可改用字典，空间为 \(O(n)\)。

**独立参考解答（非原书摘录）**

设 \(data[0..n-1]\) 和 \(degree[0..n-1]\) 已按层次、同层从左至右给出。先按该顺序为每个结点分配孩子—兄弟结点；扫描到第 \(i\) 个结点时，尚未归属的下一个结点恰是它的第一个孩子，随后 \(degree[i]-1\) 个结点依次为其余孩子。

~~~~c
Status BuildCSByLevel(const char data[], const int degree[], int n, CSTree *T) {
    CSTree node[MAX_TREE_SIZE];
    int next = 1;
    if (T == NULL || n < 0 || n > MAX_TREE_SIZE) return ERROR;
    *T = NULL;
    if (n == 0) return OK;

    for (int i = 0; i < n; ++i) {
        node[i] = NewCSNode(data[i]);            /* 两链接域均置 NULL */
        if (node[i] == NULL) { FreeNodeArray(node, i); return OVERFLOW; }
    }
    for (int i = 0; i < n; ++i) {
        CSTree last = NULL;
        if (degree[i] < 0 || next + degree[i] > n) {
            FreeNodeArray(node, n); return ERROR;
        }
        for (int j = 0; j < degree[i]; ++j) {
            CSTree child = node[next++];
            if (last == NULL) node[i]->firstchild = child;
            else last->nextsibling = child;
            last = child;
        }
    }
    if (next != n) { FreeNodeArray(node, n); return ERROR; }
    *T = node[0];
    return OK;
}
~~~~

\(FreeNodeArray\) 仅逐个释放该辅助数组中已分配的结点，适用于建造失败时的清理。空序列产生空树；对非空合法输入，循环结束时 \(next=n\) 等价于所有结点恰被某个双亲领取一次，也蕴含 \(\sum degree[i]=n-1\)。归纳扫描下标 \(i\) 可知，已链接部分始终是正确的层序前缀，所以最终得到原树且孩子次序不变。时间 \(O(n)\)，辅助指针数组 \(O(n)\)，成品树空间 \(O(n)\)。

