**独立参考解答（非原书摘录）**

将二叉树横向显示：先打印右子树，再打印根，最后打印左子树；每深入一层多输出固定数目的空格。于是右子树位于根的上方，左子树位于根的下方，正与题图的示例方向一致。

~~~~c
typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

static void Indent(int level) {
    for (int i = 0; i < 4 * level; ++i) putchar(' ');
}

void PrintBiTreeSideways(BiTree T, int level) {
    if (T == NULL) return;
    PrintBiTreeSideways(T->rchild, level + 1);
    Indent(level);
    putchar(T->data);
    putchar(10);
    PrintBiTreeSideways(T->lchild, level + 1);
}

/* 调用：PrintBiTreeSideways(T, 0); */
~~~~

空树不输出。对任一结点，递归调用已分别把右、左子树按相同规则完整打印；根恰在两者之间且缩进量等于其深度，故归纳可得整体树状布局正确。结点访问时间为 \(O(n)\)，递归栈 \(O(h)\)；若把实际输出的缩进空格也计入 I/O，最坏会输出 \(O(nh)\) 个字符。

**独立参考解答（非原书摘录）**

孩子—兄弟链表中，同层兄弟由 \(nextsibling\) 串成链，因此必须在同一缩进层用循环输出它们；每个结点的 \(firstchild\) 则递归到下一缩进层。

~~~~c
static void Indent(int level) {
    for (int i = 0; i < 4 * level; ++i) putchar(' ');
}

static void PrintCSForest(CSTree p, int level) {
    for (; p != NULL; p = p->nextsibling) {
        Indent(level);
        putchar(p->data);
        putchar(10);
        PrintCSForest(p->firstchild, level + 1);
    }
}

void PrintCSTree(CSTree T) {
    PrintCSForest(T, 0);
}
~~~~

对根调用时树根通常没有兄弟，\(PrintCSForest\) 仍可正确处理一片森林。空树不输出。循环保证同双亲的孩子按兄弟链次序、在相同层级输出；递归保证每个孩子的全部后代紧随其后且恰多一级缩进，故得到凹入表。结点访问 \(O(n)\)，递归栈 \(O(h)\)；计入缩进字符时输出量最坏为 \(O(nh)\)。

**独立参考解答（非原书摘录）**

孩子链表没有 \(nextsibling\) 域；同一双亲的孩子由该双亲 \(firstchild\) 所指的孩子链结点顺序给出。因此在输出当前结点后，沿这条孩子链依次递归每个孩子。

~~~~c
typedef struct ChildNode {
    int child;
    struct ChildNode *next;
} ChildNode, *ChildPtr;

typedef struct { char data; ChildPtr firstchild; } CTBox;
typedef struct {
    CTBox nodes[MAX_TREE_SIZE];
    int n, root;
} CTree;

static void Indent(int level) {
    for (int i = 0; i < 4 * level; ++i) putchar(' ');
}

static void PrintChildTree(const CTree *T, int u, int level) {
    Indent(level);
    putchar(T->nodes[u].data);
    putchar(10);
    for (ChildPtr p = T->nodes[u].firstchild; p != NULL; p = p->next)
        PrintChildTree(T, p->child, level + 1);
}

void PrintCTree(const CTree *T) {
    if (T != NULL && T->n != 0) PrintChildTree(T, T->root, 0);
}
~~~~

输入前提是孩子下标有效且结构为树；空树不输出。归纳地说，当前调用先输出唯一的根行，再按孩子链的从左到右顺序完整输出各子树，且每一层多一档缩进，所以正是题 6.71 的凹入表。每个结点和孩子链结点各访问一次，结构处理时间 \(O(n)\)，栈 \(O(h)\)；连同空格输出的字符数最坏为 \(O(nh)\)。

**独立参考解答（非原书摘录）**

按 6.73 的语法，单棵树输出为“结点标识”后可选地跟一对括号；括号内是其孩子构成的森林，森林中的相邻树用逗号分隔。孩子—兄弟链表刚好以 \(firstchild\) 指向该森林首根、以 \(nextsibling\) 串起后续根。

~~~~c
static void PrintGeneralTree(CSTree T) {
    putchar(T->data);
    if (T->firstchild != NULL) {
        putchar('(');
        for (CSTree c = T->firstchild; c != NULL; c = c->nextsibling) {
            PrintGeneralTree(c);
            if (c->nextsibling != NULL) putchar(',');
        }
        putchar(')');
    }
}

void OutputGeneralList(CSTree T) {
    if (T != NULL) PrintGeneralTree(T);
}
~~~~

空树输出空串；叶结点只输出自己的标识。对非叶结点，循环恰好按孩子的兄弟次序输出每棵子树，并且只在相邻子树之间输出一个逗号，外层括号正好包住整个孩子森林。由结构归纳，输出符合 6.73 的带标号广义表语法。每个结点和链接访问常数次，时间 \(O(n)\)，递归栈 \(O(h)\)。

**独立参考解答（非原书摘录）**

采用 6.73 的语法：树为一个大写字母，后面可选一个由逗号分隔的非空孩子森林。孩子链表版本把孩子存为 \(ChildNode\) 链，而不是把兄弟结点链接在树结点中。下面的递归下降算法允许空白字符；成功时必须刚好读完整个字符串。

~~~~c
typedef struct ChildNode {
    int child;
    struct ChildNode *next;
} ChildNode, *ChildPtr;
typedef struct { char data; ChildPtr firstchild; } CTBox;
typedef struct { CTBox nodes[MAX_TREE_SIZE]; int n, root; } CTree;

typedef struct { const char *s; int pos; CTree *T; int ok; } Parser;

static void SkipSpace(Parser *P) {
    while (P->s[P->pos] == ' ' || P->s[P->pos] == 10 || P->s[P->pos] == 9)
        ++P->pos;
}

static int NewVertex(Parser *P, char x) {
    if (P->T->n == MAX_TREE_SIZE) { P->ok = 0; return -1; }
    int u = P->T->n++;
    P->T->nodes[u].data = x;
    P->T->nodes[u].firstchild = NULL;
    return u;
}

static int ParseTree(Parser *P) {
    SkipSpace(P);
    char x = P->s[P->pos];
    if (x < 'A' || x > 'Z') { P->ok = 0; return -1; }
    ++P->pos;
    int u = NewVertex(P, x);
    if (!P->ok) return -1;

    SkipSpace(P);
    if (P->s[P->pos] != '(') return u;           /* 叶子 */
    ++P->pos;
    ChildPtr *tail = &P->T->nodes[u].firstchild;
    for (;;) {
        int v = ParseTree(P);                     /* 空括号不是合法森林 */
        if (!P->ok) return -1;
        ChildPtr e = malloc(sizeof *e);
        if (e == NULL) { P->ok = 0; return -1; }
        e->child = v; e->next = NULL;
        *tail = e; tail = &e->next;

        SkipSpace(P);
        if (P->s[P->pos] == ',') { ++P->pos; continue; }
        if (P->s[P->pos] == ')') { ++P->pos; return u; }
        P->ok = 0;
        return -1;
    }
}

Status CreateChildListFromGL(const char *s, CTree *T) {
    Parser P = {s, 0, T, 1};
    if (s == NULL || T == NULL) return ERROR;
    T->n = 0; T->root = -1;
    int r = ParseTree(&P);
    SkipSpace(&P);
    if (!P.ok || r < 0 || s[P.pos] != '\\0') {
        DestroyCTree(T);                          /* 释放已分配孩子链 */
        return ERROR;
    }
    T->root = r;
    return OK;
}
~~~~

\(ParseTree\) 成功返回时恰消费一棵树，读入位置停在逗号、右括号或串尾；它把每个递归返回的根下标追加到当前结点的孩子链尾部。因此按语法结构归纳，构成的孩子次序与字符序列完全一致。空串、空括号、非大写标识、括号或逗号不配对、超容量和分配失败返回错误；空树不属于 6.73 的非空树语法。设输入长度为 \(L\)、结点数为 \(n\)，时间 \(O(L)\)（结构部分为 \(O(n)\)），递归栈 \(O(h)\)，成品树空间 \(O(n)\)。

**独立参考解答（非原书摘录）**

沿孩子链表输出 6.73 的广义表。根结点先输出标识；如果有孩子，则在括号中依次递归输出孩子链的每一项，并只在相邻项之间输出逗号。

~~~~c
static void PrintChildListTree(const CTree *T, int u) {
    putchar(T->nodes[u].data);
    ChildPtr p = T->nodes[u].firstchild;
    if (p != NULL) {
        putchar('(');
        for (; p != NULL; p = p->next) {
            PrintChildListTree(T, p->child);
            if (p->next != NULL) putchar(',');
        }
        putchar(')');
    }
}

void OutputChildListGeneralList(const CTree *T) {
    if (T != NULL && T->n != 0) PrintChildListTree(T, T->root);
}
~~~~

空树输出空串，叶结点只输出一个字母。每个非叶结点的孩子链恰对应其括号内的森林，链中的 \(next\) 次序恰对应逗号分隔的从左到右次序；对每棵孩子子树递归应用同一论证即可证明输出满足 6.73 语法并表示原树。每个结点和孩子链结点处理一次，时间 \(O(n)\)，递归辅助空间 \(O(h)\)。

**独立参考解答（非原书摘录）**

以下以邻接表存储、顶点下标为 \(0..n-1\) 的简单有向图为例。对每个起点 \(s\)，深度优先搜索只允许走到下标不小于 \(s\) 的顶点；\(inPath\) 禁止当前路径重复顶点。这样一条回路只会在其最小下标顶点作为起点时输出一次。

~~~~c
static int path[MAXV], pathLen;
static int inPath[MAXV];

static void EnumerateFrom(const ALGraph *G, int s, int u) {
    for (ArcNode *a = G->vertices[u].firstarc; a != NULL; a = a->nextarc) {
        int v = a->adjvex;
        if (v == s) {
            if (pathLen > 1) OutputCircuit(path, pathLen, s);
        } else if (v > s && !inPath[v]) {
            inPath[v] = 1;
            path[pathLen++] = v;
            EnumerateFrom(G, s, v);
            --pathLen;
            inPath[v] = 0;
        }
    }
}

void AllSimpleCircuits(const ALGraph *G) {
    for (int s = 0; s < G->vexnum; ++s) {
        for (int i = 0; i < G->vexnum; ++i) inPath[i] = 0;
        path[0] = s;
        pathLen = 1;
        inPath[s] = 1;
        EnumerateFrom(G, s, s);
    }
}
~~~~

\(OutputCircuit(path,pathLen,s)\) 输出 \(path[0],\ldots,path[pathLen-1],s\)。默认简单有向图无自环，且“简单回路”长度至少为 2；若课程把自环也计为简单回路，在 \(v=s\) 时另对 \(pathLen=1\) 输出即可。若邻接表允许重弧，应先去重，否则同一顶点序列会被重复报告。

任一输出回路的顶点在当前 \(path\) 中互异，闭合弧只回到 \(s\)，故它是简单回路；反之，任一简单回路有唯一最小下标顶点 \(s\)，从该 \(s\) 沿回路方向的分支不会被下标限制剪掉，必被搜索到，且不会由其他起点再次输出。工作空间为 \(O(n)\)。设 \(P\) 为搜索到的部分简单路径数，运行时间与这些路径末端被扫描的出弧数及输出量成正比；在稠密图中为指数级，最坏 \(O(n!)\)，这与“所有回路”本身可有阶乘级输出相一致。

**独立参考解答（非原书摘录）**

用两次深度优先搜索完成强连通分量分解。第一次在 \(G\) 上按完成时刻压栈，第二次在逆图 \(G^T\) 上按出栈次序搜索；每次第二遍 DFS 所得到的顶点集合即输出为一个强连通分量。

~~~~c
static void DFSFinish(const ALGraph *G, int u, int seen[], Stack *S) {
    seen[u] = 1;
    for (ArcNode *a = G->vertices[u].firstarc; a != NULL; a = a->nextarc)
        if (!seen[a->adjvex]) DFSFinish(G, a->adjvex, seen, S);
    Push(S, u);
}

static void DFSCollect(const ALGraph *GT, int u, int seen[], Vector *C) {
    seen[u] = 1;
    VectorPush(C, u);
    for (ArcNode *a = GT->vertices[u].firstarc; a != NULL; a = a->nextarc)
        if (!seen[a->adjvex]) DFSCollect(GT, a->adjvex, seen, C);
}

Status StronglyConnectedComponents(const ALGraph *G) {
    ALGraph GT;
    Stack S;
    int seen[MAXV] = {0};
    if (BuildTranspose(G, &GT) == ERROR) return ERROR;
    InitStack(&S);
    for (int u = 0; u < G->vexnum; ++u)
        if (!seen[u]) DFSFinish(G, u, seen, &S);

    for (int u = 0; u < G->vexnum; ++u) seen[u] = 0;
    while (!StackEmpty(S)) {
        int u;
        Pop(&S, &u);
        if (!seen[u]) {
            Vector C; InitVector(&C);
            DFSCollect(&GT, u, seen, &C);
            OutputComponent(&C);
            DestroyVector(&C);
        }
    }
    DestroyStack(&S);
    DestroyGraph(&GT);
    return OK;
}
~~~~

\(BuildTranspose\) 在线性扫描原邻接表时把每条弧 \(u\to v\) 改挂为 \(v\to u\)。第一次 DFS 的完成顺序对应强连通分量缩点 DAG 的拓扑后序；按其逆序在 \(G^T\) 搜索不会越过当前尚未输出的分量，因此恰收集一个强连通分量。孤立顶点会作为单元素分量输出，图不连通也由外层循环覆盖。两次 DFS、建逆图均处理每个顶点和弧常数次，时间 \(O(|V|+|E|)\)；若逆表需新建，额外空间 \(O(|V|+|E|)\)，已有逆邻接表时工作空间为 \(O(|V|)\)。

**独立参考解答（非原书摘录）**

设输入为带权无向图的邻接表（每条无向边在两端各出现一次），边权均为有限值。对每个尚未纳入的顶点启动一次 Prim；该次 Prim 结束时正好得到一个连通分量的最小生成树。被选中顶点 \(u\) 的 \(parent[u]\) 已在树中，故把 \(u\) 追加为它的孩子；没有双亲的起点则追加到森林根的兄弟链。

~~~~c
typedef struct CSNode {
    VertexType data;
    struct CSNode *firstchild, *nextsibling;
} CSNode, *CSForest;

Status PrimMinimumSpanningForest(const ALGraph *G, CSForest *F) {
    int in[MAXV] = {0}, parent[MAXV];
    Weight low[MAXV];
    CSNode *node[MAXV] = {0}, *lastChild[MAXV] = {0}, *lastRoot = NULL;
    const Weight INF = InfinityWeight();
    *F = NULL;
    for (int v = 0; v < G->vexnum; ++v) {
        low[v] = INF;
        parent[v] = -1;
    }

    for (int s = 0; s < G->vexnum; ++s) {
        if (in[s]) continue;
        low[s] = 0;
        for (;;) {
            int u = -1;
            for (int v = 0; v < G->vexnum; ++v)
                if (!in[v] && (u == -1 || low[v] < low[u])) u = v;
            if (u == -1 || low[u] == INF) break; /* 当前分量已完成 */

            in[u] = 1;
            node[u] = NewCSNode(G->vertices[u].data);
            if (node[u] == NULL) { DestroyCSForest(*F); return OVERFLOW; }
            if (parent[u] == -1) {
                if (*F == NULL) *F = node[u];
                else lastRoot->nextsibling = node[u];
                lastRoot = node[u];
            } else {
                CSNode *p = node[parent[u]];
                if (p->firstchild == NULL) p->firstchild = node[u];
                else lastChild[parent[u]]->nextsibling = node[u];
                lastChild[parent[u]] = node[u];
            }
            for (ArcNode *a = G->vertices[u].firstarc; a != NULL; a = a->nextarc) {
                int v = a->adjvex;
                if (!in[v] && a->weight < low[v]) {
                    low[v] = a->weight;
                    parent[v] = u;
                }
            }
        }
    }
    return OK;
}
~~~~

空图返回空森林；孤立顶点以单结点树加入根兄弟链。每次选择的 \(u\) 都由当前已选集合与未选集合之间的最轻边连接（分量起点除外），由割性质可安全加入；一轮结束后覆盖且仅覆盖一个连通分量，因此所有轮次合起来是最小生成森林。每个选择线性扫描 \(|V|\) 个候选，所有邻接边扫描一次，时间 \(O(|V|^2+|E|)\)，对简单图为 \(O(|V|^2)\)；辅助数组 \(O(|V|)\)，输出森林 \(O(|V|)\)。相等边权的任选规则可能产生不同但同样最优的森林。

